<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('hotspot','create');global $conn;$tenantId=(int)getCurrentTenantId();$error='';$routers=[];
$q=$conn->prepare("SELECT id,COALESCE(name,router_name) name FROM mikrotik_routers WHERE tenant_id=? AND status='active' ORDER BY name");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$routers[]=$r;$q->close();}
$v=['name'=>'','duration_minutes'=>'60','price'=>'','router_id'=>'','status'=>'active'];
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();foreach($v as $k=>$d)$v[$k]=trim((string)($_POST[$k]??$d));$name=$v['name'];$mins=(int)$v['duration_minutes'];$price=(float)$v['price'];$rid=(int)$v['router_id'];if($name==='')$error='Plan name is required.';elseif($mins<1)$error='Duration must be at least 1 minute.';elseif($price<0)$error='Price cannot be negative.';elseif(!$rid)$error='Assign an active MikroTik router.';else{$q=$conn->prepare("INSERT INTO hotspot_packages(tenant_id,name,duration_minutes,price,status,router_id) VALUES(?,?,?,?,?,?)");if($q){$q->bind_param('iidssi',$tenantId,$name,$mins,$price,$v['status'],$rid);if($q->execute())redirect('packages.php');$error=$q->error;$q->close();}else$error='Unable to create hotspot plan.';}}
$pageTitle='Add Hotspot Plan';require_once '../includes/header.php';?>
<div class="page-content"><div class="page-header"><div><h1>Add Hotspot Plan</h1><p>Define the package duration, price and MikroTik router that will authorize customers.</p></div><a class="btn btn-secondary" href="packages.php">Back</a></div>
<div class="card" style="max-width:760px;padding:22px"><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="form-grid"><label>Plan Name *<input name="name" value="<?=e($v['name'])?>" required></label><label>Duration (minutes) *<input type="number" min="1" name="duration_minutes" value="<?=e($v['duration_minutes'])?>" required></label><label>Price *<input type="number" step="0.01" min="0" name="price" value="<?=e($v['price'])?>" required></label><label>MikroTik Router *<select name="router_id" required><option value="">Select router</option><?php foreach($routers as $r):?><option value="<?=$r['id']?>" <?=$v['router_id']==$r['id']?'selected':''?>><?=e($r['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label></div><button class="btn btn-primary">Save Hotspot Plan</button></form></div></div><?php require_once '../includes/footer.php';?>